let cur=0,mode='side',tf={s:1,x:0,y:0},selI=-1,swipeX=.5;
const stage=document.getElementById('stage');
const tabs=document.getElementById('tabs');
F.forEach((f,i)=>{const b=document.createElement('button');b.textContent=f.name;b.onclick=()=>show(i);tabs.appendChild(b)});
document.querySelectorAll('[data-m]').forEach(b=>b.onclick=()=>{mode=b.dataset.m;document.querySelectorAll('[data-m]').forEach(x=>x.classList.toggle('on',x===b));build()});
document.getElementById('op').oninput=()=>apply();document.getElementById('mkon').onchange=()=>build();
