function pane(cap,imgs){const p=document.createElement('div');p.className='pane';const c=document.createElement('div');c.className='cap';c.textContent=cap;p.appendChild(c);
 const L=document.createElement('div');L.className='layer';imgs.forEach(([src,cls])=>{const im=new Image();im.src=src;im.className=cls||'';L.appendChild(im)});
 if(document.getElementById('mkon').checked)F[cur].marks.forEach((m,i)=>{if(!m.p)return;const d=document.createElement('div');d.className='mk'+(i===selI?' sel':'');d.style.left=m.p[0]+'px';d.style.top=m.p[1]+'px';L.appendChild(d)});
 p.appendChild(L);stage.appendChild(p);return p}
function build(){stage.innerHTML='';const f=F[cur];
 const R=(f.g&&document.getElementById('rsel').value==='g')?f.g:f.p;
 if(mode==='side'){pane('원본 CAD',[[f.o]]);if(f.g)pane(f.gname,[[f.g]]);pane('수정 후 · 2026-10-14',[[f.p]])}
 else if(mode==='over'){pane('겹치기: 원본 위에 결과',[[f.o],[R,'top']])}
 else{const p=pane('스와이프: 왼쪽 원본 | 오른쪽 결과',[[f.o],[R,'top']]);const s=document.createElement('div');s.id='swipe';p.appendChild(s);
  s.onpointerdown=e=>{e.stopPropagation();s.setPointerCapture(e.pointerId);s.onpointermove=ev=>{const r=p.getBoundingClientRect();swipeX=Math.min(1,Math.max(0,(ev.clientX-r.left)/r.width));apply()};s.onpointerup=()=>s.onpointermove=null}}
 stage.querySelectorAll('.pane').forEach(p=>{p.onwheel=e=>{e.preventDefault();const r=p.getBoundingClientRect(),mx=e.clientX-r.left,my=e.clientY-r.top,k=Math.exp(-e.deltaY*0.0015);
   tf.x=mx-(mx-tf.x)*k;tf.y=my-(my-tf.y)*k;tf.s*=k;apply()};
  p.onpointerdown=e=>{p.setPointerCapture(e.pointerId);const sx=e.clientX,sy=e.clientY,ox=tf.x,oy=tf.y;p.style.cursor='grabbing';
   p.onpointermove=ev=>{tf.x=ox+ev.clientX-sx;tf.y=oy+ev.clientY-sy;apply()};p.onpointerup=()=>{p.onpointermove=null;p.style.cursor='grab'}}});
 apply()}
function apply(){const op=parseFloat(document.getElementById('op').value);
 stage.querySelectorAll('.pane').forEach(p=>{const L=p.querySelector('.layer');L.style.transform=`translate(${tf.x}px,${tf.y}px) scale(${tf.s})`;
  const t=L.querySelector('img.top');if(t){if(mode==='over'){t.style.opacity=op;t.style.clipPath='none'}else{t.style.opacity=1;const w=p.clientWidth;const cx=(swipeX*w-tf.x)/tf.s;t.style.clipPath=`inset(0 0 0 ${cx}px)`}}
  const s=p.querySelector('#swipe');if(s)s.style.left=(swipeX*p.clientWidth-1)+'px'})}
function fit(){const f=F[cur];const w=(mode==='side'?stage.clientWidth/(f.g?3:2):stage.clientWidth),h=stage.clientHeight;tf.s=Math.min(w/f.w,h/f.h)*0.98;tf.x=(w-f.w*tf.s)/2;tf.y=(h-f.h*tf.s)/2}
function show(i){cur=i;selI=-1;[...tabs.children].forEach((b,j)=>b.classList.toggle('on',j===i));const f=F[i];
 const I=f.info;document.getElementById('inf').innerHTML=`<b>${f.name}</b> <small>${f.src}</small><br>실 ${I.rooms} · 문 ${I.stats.doors_open} · 미닫이 ${I.stats.sliding||0} · 창 ${I.stats.windows} · 실내창 ${I.stats.windows_inner||0}<br>`+(f.fire?`소방: 감지기 ${f.fire.detector||0} · 피난구유도등 ${f.fire.exit_sign||0} · 통로유도등 ${f.fire.corridor_light||0} · 소화전 ${f.fire.hydrant||0}<br>`:'')+
  (I.heal&&I.heal['형상_실']!==undefined?`<br>`:'')+(I.use?`용도 ${I.use} · 층고 ${I.h}m · 반자 ${I.ceil??'없음'}<br>정렬: ${I.align}<br>`:'')+`보정: ${Object.entries(I.heal).map(([k,v])=>k+' '+v).join(', ')}`;
 const L=document.getElementById('list');L.innerHTML='';document.getElementById('cnt').textContent=f.marks.length+'건';
 f.marks.forEach((m,j)=>{const d=document.createElement('div');d.className='it';d.innerHTML=`<b>${m.t}</b> <small>${m.d}</small>${m.p?'':' <small>(위치 없음)</small>'}`;
  d.onclick=()=>{selI=j;[...L.children].forEach((x,k)=>x.classList.toggle('sel',k===j));if(m.p){const w=(mode==='side'?stage.clientWidth/(F[cur].g?3:2):stage.clientWidth),h=stage.clientHeight;tf.s=Math.max(tf.s,0.9);tf.x=w/2-m.p[0]*tf.s;tf.y=h/2-m.p[1]*tf.s}build()};L.appendChild(d)});
 build();fit();apply()}
if(F.some(f=>f.g)){const r=document.getElementById('rsel');r.style.display='';r.onchange=()=>build()}
addEventListener('resize',()=>apply());show(0);
